HloModule fused

ENTRY main {
  A = f32[128,256] parameter(0)
  B = f32[256,64]  parameter(1)
  C = f32[128,64]  parameter(2)
  d = f32[128,64]  dot(A, B),
        lhs_contracting_dims={1}, rhs_contracting_dims={0}
  ROOT r = f32[128,64] add(d, C)
}

// Fragment 1 (Affine)
affine.for %i = 0 to %N step 1 {
  affine.for %j = 0 to %M step 4 {
    %v = affine.load %A[%i, %j + 1] : memref<?x?xf32>
    affine.store %v, %B[%j, %i] : memref<?x?xf32>
  }
}

// Fragment 2 (Uses data-dependent bound)
affine.for %i = 0 to %N step 1 {
  %k = memref.load %indices[%i] : memref<?xi32>
  %kidx = arith.index_cast %k : i32 to index
  affine.for %j = 0 to %kidx step 1 {  // <-- bound is data-dependent
    %v = affine.load %A[%i, %j] : memref<?x?xf32>
    affine.store %v, %B[%i, %j] : memref<?x?xf32>
  }
}

// Before conversion (arith on builtin types)
func.func @add(%a: i32, %b: i32) -> i32 {
  %0 = arith.addi %a, %b : i32
  return %0 : i32
}

// Target after full conversion (LLVM Dialect)
llvm.func @add(%a: i32, %b: i32) -> i32 {
  %0 = llvm.add %a, %b : i32
  llvm.return %0 : i32
}

gpu.module @kernels {
  gpu.func @kernel(%arg: memref<1024xf32, 1>) kernel {
    %tid = gpu.thread_id x
    %bid = gpu.block_id  x
    %idx = arith.addi %bid, %tid : index
    %v   = memref.load %arg[%idx] : memref<1024xf32, 1>
    gpu.return
  }
}

func.func @host(%a: memref<1024xf32, 1>) {
  %c1  = arith.constant 1  : index
  %c256 = arith.constant 256 : index
  %c4   = arith.constant 4   : index
  gpu.launch_func @kernels::@kernel
     blocks in (%c4, %c1, %c1)
     threads in (%c256, %c1, %c1)
     args(%a : memref<1024xf32, 1>)
  return
}

