// Input
func.func @f(%x: i32) -> i32 {
  %c0 = arith.constant 0 : i32
  %c1 = arith.constant 1 : i32
  %0  = arith.addi %x, %c0 : i32   // add-zero
  %1  = arith.muli %0, %c1 : i32   // mul-one
  %2  = arith.subi %1, %1 : i32    // x - x
  return %2 : i32
}

